/**
 * A score as a row of marks (`design/components/rating.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rating.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  ratingModel,
  ratingPress,
  roveRating,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/rating.module.css'

export type RatingSize = NonNullable<RatingProps['size']>

export interface RatingMessages {
  /** A mark's name, from the value it sets and that value's numeral: "3 stars". */
  mark: (value: number, numeral: string) => string
  /** The shown rating's name, one sentence: "Rating: 4.3 out of 5". */
  shown: (label: string, value: string, max: string) => string
}

export interface RatingProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField, which names the group with its label.
   */
  'aria-labelledby'?: string
  /**
   * A required rating cannot be cleared by a press.
   */
  'aria-required'?: boolean
  defaultValue?: number | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * The rating's name. A control's group is named by it ("Rate this answer") unless a FormField
   * names it, and a shown rating's sentence starts with it ("Average rating").
   */
  label: string
  /**
   * Writes the numerals of the marks' names and the shown sentence. Defaults to the page's own.
   */
  locale?: string
  /**
   * The number of marks: a whole number from 2 to 10. Default 5.
   */
  max?: number
  messages?: RatingMessages
  /**
   * Posts the value as a whole number, or nothing when the rating holds none.
   */
  name?: string
  /**
   * The value a press or a key chose, or `null` when a press cleared it. Never called for a
   * shown rating.
   */
  onChange?: (value: number | null) => void
  /**
   * Shows the rating as an image a reader reads and cannot change.
   */
  readOnly?: boolean
  /**
   * The marks' size: the icon sizes. A control's hit targets stay one size.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * What the rating holds. A control holds a whole number from 1 to `max`, or `null` for no
   * rating. A shown rating holds any value from 0 to `max`, drawn to one decimal place.
   */
  value?: number | null
}

/** A score as a row of marks. */
export default function Rating(given: RatingProps): JSX.Element {
  const props = mergeProps(
    { readOnly: false, disabled: false, invalid: false, size: 'md' } as Defaults<
      RatingProps,
      'readOnly' | 'disabled' | 'invalid' | 'size'
    >,
    claimSlot(given, 'group'),
  )
  return scope(() => {
    const mirror = createCell(props.defaultValue ?? null)
    const root = elementRef<HTMLElement>()
    const model = createDerived(() =>
      ratingModel({
        value: props.value === undefined ? mirror.value : props.value,
        label: props.label,
        max: props.max,
        readOnly: props.readOnly,
        locale: props.locale,
        messages: props.messages,
      }),
    )
    const settle = createDerived(
      () => (next: number | null) =>
        next !== model.value.value && ((mirror.value = next), props.onChange?.(next), true),
    )
    const stop = createDerived(() => model.value.value ?? 1)
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'Rating',
        element: () => root.value,
        state: () => ({
          value: model.value.value,
          max: model.value.max,
          readonly: props.readOnly,
          disabled: props.disabled,
          invalid: props.invalid,
        }),
        actions: {
          set: {
            argument: 'number',
            run: (value) =>
              (() => {
                if (props.readOnly) throw new Error('The rating is shown and takes no press.')
                if (!Number.isInteger(value) || value < 1 || value > model.value.max) {
                  throw new Error(`A rating is a whole number from 1 to ${model.value.max}.`)
                }
                settle.value(value)
              })(),
          },
          clear: () =>
            (() => {
              if (props.readOnly) throw new Error('The rating is shown and takes no press.')
              if (props['aria-required'] === true)
                throw new Error('A required rating keeps its mark.')
              settle.value(null)
            })(),
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <>
        {props.readOnly ? (
          <span
            class={styles.rating}
            id={props.id}
            role="img"
            aria-label={model.value.sentence}
            aria-describedby={props['aria-describedby']}
            data-size={props.size}
            data-readonly={''}
            data-member="rating"
            ref={root.attach}
          >
            <Each of={model.value.marks} by={(mark) => mark.value} renew>
              {(mark) => (
                <span class={styles.mark} data-fill={mark.fill}>
                  <span class={styles.glyph}>
                    <Icon name="rating" size={props.size} />
                    <span class={styles.fill} style={{ 'inline-size': mark.share }}>
                      <Icon name="rating" size={props.size} />
                    </span>
                  </span>
                </span>
              )}
            </Each>
            {props.name !== undefined ? (
              <input
                type="hidden"
                name={props.name}
                value={model.value.value === null ? '' : String(model.value.value)}
                disabled={props.disabled && !props.readOnly}
              />
            ) : null}
          </span>
        ) : (
          <span
            class={styles.rating}
            id={props.id}
            role="radiogroup"
            aria-label={props.label}
            aria-labelledby={props['aria-labelledby']}
            aria-describedby={props['aria-describedby']}
            aria-required={props['aria-required'] === true ? true : undefined}
            aria-invalid={props.invalid ? true : undefined}
            data-size={props.size}
            data-disabled={props.disabled ? '' : undefined}
            data-invalid={props.invalid ? '' : undefined}
            data-member="rating"
            ref={root.attach}
          >
            <Each of={model.value.marks} by={(mark) => mark.value} renew>
              {(mark) => (
                <button
                  class={styles.mark}
                  type="button"
                  role="radio"
                  aria-checked={mark.value === model.value.value}
                  aria-label={mark.name}
                  disabled={props.disabled}
                  tabindex={mark.value === stop.value ? 0 : -1}
                  data-fill={mark.fill}
                  onclick={() =>
                    settle.value(
                      ratingPress(mark.value, model.value.value, props['aria-required'] === true),
                    )
                  }
                  onkeydown={($event: KeyboardEvent) => roveRating($event, settle.value)}
                >
                  <span class={styles.glyph}>
                    <Icon name="rating" size={props.size} />
                    <span class={styles.fill} style={{ 'inline-size': mark.share }}>
                      <Icon name="rating" size={props.size} />
                    </span>
                  </span>
                </button>
              )}
            </Each>
            {props.name !== undefined ? (
              <input
                type="hidden"
                name={props.name}
                value={model.value.value === null ? '' : String(model.value.value)}
                disabled={props.disabled && !props.readOnly}
              />
            ) : null}
          </span>
        )}
      </>
    )
  })
}

Rating.controlKind = 'group'
